  --gap: 24px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: 'Inter', system-ui, -apple-system, Segoe UI, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

a {
  color: inherit;
  text-decoration: none;
}

a:hover { text-decoration: underline; }

a:focus-visible,
button:focus-visible,
input:focus-visible,
[tabindex]:focus-visible {
  outline: 3px solid var(--highlight);
  outline-offset: 3px;
  border-radius: 6px;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--ink);
  color: #fff;
  padding: 12px 18px;
  z-index: 1000;
  border-radius: 0 0 8px 0;
  font-weight: 600;
}
.skip-link:focus { left: 0; }

.container {
  max-width: var(--max);
  margin: 0 auto;
  padding: 0 24px;
}

h1, h2, h3, h4 {
  font-family: 'Fraunces', Georgia, serif;
  font-weight: 600;
  letter-spacing: -0.01em;
  margin: 0 0 12px;
  line-height: 1.15;
}

.eyebrow {
  font-family: 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 12px;
  font-weight: 600;
  color: var(--ink-muted);
  margin: 0 0 10px;
}

/* ===== Top announcement bar ===== */
.announce {
  background: var(--ink);
  color: #fff;
  font-size: 13px;
  text-align: center;
  padding: 10px 16px;
  letter-spacing: 0.02em;
}
.announce strong { color: #f7d28a; }

/* ===== Header ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250, 250, 247, 0.92);
  backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  padding: 16px 0;
}
.brand {
  font-family: 'Fraunces', serif;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.02em;
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.brand-mark {
  width: 28px; height: 28px; border-radius: 8px;
  background: var(--accent);
  color: #fff;
  display: inline-grid; place-items: center;
  font-size: 14px; font-weight: 700;
  font-family: 'Inter', sans-serif;
}
.primary-nav ul {
  list-style: none; padding: 0; margin: 0;
  display: flex; gap: 28px; justify-content: center;
}
.primary-nav a {
  font-weight: 500; font-size: 15px; padding: 8px 2px;
  position: relative;
}
.primary-nav a::after {
  content: ''; position: absolute; left: 0; right: 0; bottom: 2px;
  height: 2px; background: var(--ink); transform: scaleX(0);
  transform-origin: left; transition: transform .25s ease;
}
.primary-nav a:hover { text-decoration: none; }
.primary-nav a:hover::after { transform: scaleX(1); }

.header-actions {
  display: flex; align-items: center; gap: 8px;
}
.icon-btn {
  appearance: none; border: none; background: transparent;
  color: var(--ink); padding: 10px; border-radius: 999px;
  cursor: pointer; display: inline-grid; place-items: center;
  position: relative;
}
.icon-btn:hover { background: var(--surface-alt); }
.cart-badge {
  position: absolute; top: 4px; right: 4px;
  background: var(--highlight); color: #fff;
  font-size: 10px; font-weight: 700;
  min-width: 18px; height: 18px; padding: 0 5px; border-radius: 999px;
  display: inline-grid; place-items: center;
}

/* ===== Buttons ===== */
.btn {
  appearance: none; border: 1px solid transparent;
  font: inherit; font-weight: 600;
  padding: 12px 22px; border-radius: 999px;
  cursor: pointer; display: inline-flex; align-items: center; gap: 8px;
  transition: transform .15s ease, background .2s ease, color .2s ease;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--ink); color: #fff;
}
.btn-primary:hover { background: var(--accent); }
.btn-outline {
  background: transparent; color: var(--ink);
  border-color: var(--ink);
}
.btn-outline:hover { background: var(--ink); color: #fff; }
.btn-light {
  background: #fff; color: var(--ink);
}
.btn-light:hover { background: var(--surface-alt); }

/* ===== Hero ===== */
.hero {
  padding: 36px 0 48px;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 32px;
  align-items: stretch;
}
.hero-copy {
  background: var(--surface-alt);
  border-radius: var(--radius-lg);
  padding: 56px 48px;
  display: flex; flex-direction: column; justify-content: center;
  position: relative; overflow: hidden;
}
.hero-copy h1 {
  font-size: clamp(36px, 5vw, 64px);
  margin-bottom: 18px;
}
.hero-copy h1 em {
  font-style: italic; color: var(--accent);
}
.hero-copy p {
  font-size: 17px; color: var(--ink-muted);
  max-width: 46ch; margin: 0 0 28px;
}
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }
.hero-meta {
  margin-top: 36px; display: flex; gap: 28px;
  border-top: 1px solid var(--border); padding-top: 20px;
}
.hero-meta div strong {
  font-family: 'Fraunces', serif; font-size: 22px; display: block;
}
.hero-meta div span { font-size: 13px; color: var(--ink-muted); }

.hero-visual {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  min-height: 460px;
  background: linear-gradient(135deg, #c7b9a3 0%, #8a7a63 100%);
  isolation: isolate;
}
.hero-visual::before {
  content: '';
  position: absolute; inset: 0;
  background:
    radial-gradient(60% 60% at 75% 25%, rgba(255,255,255,.35), transparent 60%),
    radial-gradient(50% 50% at 25% 80%, rgba(0,0,0,.28), transparent 70%);
}
.hero-visual::after {
  content: '';
  position: absolute; left: 50%; top: 50%;
  transform: translate(-50%, -50%);
  width: 65%; aspect-ratio: 1;
  background: radial-gradient(circle at 30% 30%, #fff5e1, #b27a4a 60%, #5c3a1f 100%);
  border-radius: 50%;
  box-shadow: 0 30px 60px rgba(0,0,0,0.25);
}
.hero-tag {
  position: absolute; left: 24px; bottom: 24px;
  background: rgba(255,255,255,0.9);
  padding: 12px 16px; border-radius: 999px;
  font-size: 13px; font-weight: 600;
  display: inline-flex; align-items: center; gap: 8px;
  z-index: 2;
}
.hero-tag .dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--highlight);
}

/* ===== Logo strip ===== */
.logos {
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 24px 0;
}
.logos-row {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between;
  gap: 20px; color: var(--ink-muted);
}
.logos-row .logo-item {
  font-family: 'Fraunces', serif;
  font-weight: 600;
  font-size: 18px;
  letter-spacing: 0.02em;
  opacity: 0.7;
}

/* ===== Section ===== */
section { padding: 56px 0; }
.section-head {
  display: flex; align-items: end; justify-content: space-between;
  gap: 24px; margin-bottom: 32px;
}
.section-head h2 {
  font-size: clamp(28px, 3.4vw, 40px);
}
.section-head p { color: var(--ink-muted); margin: 0; max-width: 52ch; }
.section-head .head-link { font-weight: 600; white-space: nowrap; }

/* ===== Category pills ===== */
.pills {
  display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 28px;
}
.pill {
  appearance: none; border: 1px solid var(--border); background: #fff;
  color: var(--ink); font: inherit; font-weight: 500;
  padding: 10px 18px; border-radius: 999px; cursor: pointer;
  transition: background .2s, color .2s, border-color .2s;
}
.pill:hover { border-color: var(--ink); }
.pill[aria-pressed="true"] {
  background: var(--ink); color: #fff; border-color: var(--ink);
}

/* ===== Product grid ===== */
.products {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
}
.product-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform .2s ease, box-shadow .2s ease;
}
.product-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}
.product-media {
  position: relative;
  aspect-ratio: 4/5;
  background: var(--surface-alt);
  display: grid; place-items: center;
  overflow: hidden;
}
.product-media .swatch {
  width: 70%; height: 70%; border-radius: 18px;
  background: linear-gradient(145deg, var(--c1, #d8c7a6), var(--c2, #8a7355));
  box-shadow: inset 0 -20px 40px rgba(0,0,0,0.12), 0 12px 24px rgba(0,0,0,0.08);
}
.badge {
  position: absolute; top: 12px; left: 12px;
  background: #fff; color: var(--ink);
  font-size: 11px; font-weight: 700; letter-spacing: 0.08em;
  padding: 6px 10px; border-radius: 999px;
  text-transform: uppercase;
}
.badge.sale { background: var(--highlight); color: #fff; }
.badge.new { background: var(--accent); color: #fff; }
.wishlist {
  position: absolute; top: 10px; right: 10px;
  width: 36px; height: 36px;
  border: none; background: rgba(255,255,255,0.92);
  border-radius: 50%; cursor: pointer;
  display: grid; place-items: center;
  color: var(--ink);
}
.wishlist:hover { background: #fff; }
.wishlist[aria-pressed="true"] { color: var(--highlight); }

.product-body {
  padding: 16px 18px 20px;
  display: flex; flex-direction: column; gap: 6px; flex: 1;
}
.product-cat {
  font-size: 12px; color: var(--ink-muted); letter-spacing: 0.06em;
  text-transform: uppercase;
}
.product-name {
  font-family: 'Fraunces', serif;
  font-size: 18px; font-weight: 600;
  margin: 0;
}
.product-rating {
  display: flex; align-items: center; gap: 6px;
  font-size: 13px; color: var(--ink-muted);
}
.stars { color: #e1a32a; letter-spacing: 1px; font-size: 13px; }
.product-price {
  margin-top: 8px;
  display: flex; align-items: center; gap: 8px;
}
.price { font-weight: 700; font-size: 17px; }
.price-old {
  color: var(--ink-muted); text-decoration: line-through; font-size: 14px;
}
.add-cart {
  margin-top: 10px;
  width: 100%; padding: 11px 16px;
  border-radius: 10px;
  background: var(--ink); color: #fff;
  border: none; font-weight: 600; cursor: pointer;
  transition: background .2s;
}
.add-cart:hover { background: var(--accent); }
.add-cart.added { background: var(--accent); }

/* ===== Deals ===== */
.deals {
  background: var(--ink);
  color: #fff;
}
.deals .eyebrow { color: rgba(255,255,255,0.65); }
.deals h2 { color: #fff; }
.deals p { color: rgba(255,255,255,0.7); }
.deal-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: var(--gap);
}
.deal-card {
  border-radius: var(--radius-lg);
  padding: 32px;
  min-height: 280px;
  display: flex; flex-direction: column; justify-content: space-between;
  position: relative; overflow: hidden;
  isolation: isolate;
  color: #fff;
}
.deal-card .deal-tag {
  font-size: 12px; font-weight: 700; letter-spacing: 0.12em;
  text-transform: uppercase;
  background: rgba(255,255,255,0.18);
  padding: 6px 12px; border-radius: 999px;
  align-self: flex-start;
  backdrop-filter: blur(6px);
}
.deal-card h3 {
  font-size: 30px; line-height: 1.1; margin: 18px 0 8px;
  color: #fff;
}
.deal-card p { color: rgba(255,255,255,0.85); margin: 0 0 18px; max-width: 36ch; }
.deal-card .btn { align-self: flex-start; }
.deal-card.feature {
  background: linear-gradient(135deg, #4a6b3a 0%, #2c4022 100%);
  grid-row: span 2;
}
.deal-card.feature::after {
  content: ''; position: absolute; right: -60px; bottom: -60px;
  width: 280px; height: 280px; border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #f1e6c8, #c8a967);
  opacity: 0.85; z-index: -1;
}
.deal-card.warm {
  background: linear-gradient(135deg, #b8553d 0%, #6d2a1a 100%);
}
.deal-card.warm::after {
  content: ''; position: absolute; right: -40px; top: -40px;
  width: 180px; height: 180px; border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #ffd9b3, #d97842);
  z-index: -1;
}
.deal-card.cool {
  background: linear-gradient(135deg, #2f5b6e 0%, #14323f 100%);
}
.deal-card.cool::after {
  content: ''; position: absolute; right: -40px; bottom: -40px;
  width: 200px; height: 200px; border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #cfe9f1, #5b97ad);
  z-index: -1;
}
.countdown {
  display: flex; gap: 10px; margin-top: 8px;
}
.countdown .unit {
  background: rgba(0,0,0,0.3);
  padding: 8px 12px; border-radius: 8px;
  text-align: center; min-width: 56px;
  font-variant-numeric: tabular-nums;
}
.countdown .unit b {
  font-family: 'Fraunces', serif;
  font-size: 22px; display: block; line-height: 1;
}
.countdown .unit span {
  font-size: 10px; text-transform: uppercase; letter-spacing: 0.12em;
  color: rgba(255,255,255,0.7);
}

/* ===== Editorial ===== */
.editorial-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--gap);
}
.article-card {
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--border);
  display: flex; flex-direction: column;
  transition: transform .2s ease, box-shadow .2s ease;
}
.article-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.article-media {
  aspect-ratio: 16/10;
  background: var(--surface-alt);
  position: relative;
  overflow: hidden;
}
.article-media .scene {
  position: absolute; inset: 0;
}
.scene.s1 { background: linear-gradient(135deg, #e8dcc4 0%, #b59870 100%); }
.scene.s1::after {
  content: ''; position: absolute; left: 20%; bottom: 0;
  width: 60%; height: 70%; border-radius: 30% 30% 0 0;
  background: linear-gradient(180deg, #f5ead0, #c9a86b);
}
.scene.s2 { background: linear-gradient(135deg, #2a4a3e 0%, #14241e 100%); }
.scene.s2::after {
  content: ''; position: absolute; left: 50%; top: 50%;
  transform: translate(-50%, -50%);
  width: 55%; aspect-ratio: 1; border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #b8c9bd, #5a7a68 60%, #2a3f36);
}
.scene.s3 { background: linear-gradient(135deg, #d6bdb0 0%, #7a534a 100%); }
.scene.s3::after {
  content: ''; position: absolute; left: 15%; top: 25%;
  width: 70%; height: 60%; border-radius: 8px;
  background: linear-gradient(180deg, #f3e6dc, #c2a392);
  box-shadow: 0 10px 30px rgba(0,0,0,0.2);
}
.article-body {
  padding: 22px;
  display: flex; flex-direction: column; gap: 8px; flex: 1;
}
.article-meta {
  display: flex; gap: 12px;
  font-size: 12px; color: var(--ink-muted);
  text-transform: uppercase; letter-spacing: 0.08em; font-weight: 600;
}
.article-meta .tag { color: var(--accent); }
.article-card h3 {
  font-size: 22px; margin: 4px 0 6px;
}
.article-card p { color: var(--ink-muted); margin: 0; font-size: 15px; }
.article-card .read-more {
  margin-top: auto; padding-top: 16px;
  font-weight: 600; display: inline-flex; align-items: center; gap: 6px;
}

/* ===== Newsletter ===== */
.newsletter {
  background: var(--surface-alt);
  border-radius: var(--radius-lg);
  padding: 56px;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 40px;
  align-items: center;
}
.newsletter h2 { font-size: clamp(26px, 3vw, 36px); margin-bottom: 8px; }
.newsletter p { color: var(--ink-muted); margin: 0 0 20px; }
.newsletter form {
  display: flex; gap: 8px; max-width: 460px;
}
.newsletter label {
  position: absolute; left: -9999px;
}
.newsletter input[type="email"] {
  flex: 1; padding: 14px 18px;
  border: 1px solid var(--border);
  border-radius: 999px; background: #fff;
  font: inherit; font-size: 15px;
}
.newsletter input[type="email"]:focus { border-color: var(--ink); }
.newsletter .form-status {
  margin-top: 10px; font-size: 13px; color: var(--accent); font-weight: 600;
  min-height: 18px;
}
.newsletter-visual {
  border-radius: var(--radius);
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #1f3a2e 0%, #0d1f17 100%);
  position: relative; overflow: hidden;
}
.newsletter-visual::after {
  content: ''; position: absolute; left: 50%; top: 50%;
  transform: translate(-50%, -50%);
  width: 70%; aspect-ratio: 1; border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #e8d9b8, #b08a4e 60%, #5a3f1c);
  box-shadow: 0 30px 60px rgba(0,0,0,0.3);
}

/* ===== Footer ===== */
footer {
  background: var(--bg);
  border-top: 1px solid var(--border);
  padding: 56px 0 28px;
  margin-top: 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 40px;
  margin-bottom: 40px;
}
.footer-brand p {
  color: var(--ink-muted); max-width: 36ch; margin: 12px 0 16px;
}
.footer-col h4 {
  font-family: 'Inter', sans-serif;
  font-size: 13px; text-transform: uppercase; letter-spacing: 0.12em;
  margin: 0 0 14px; color: var(--ink-muted);
}
.footer-col ul {
  list-style: none; padding: 0; margin: 0;
  display: flex; flex-direction: column; gap: 10px;
}
.footer-col a { font-size: 15px; }
.socials { display: flex; gap: 8px; }
.socials a {
  width: 36px; height: 36px; border-radius: 50%;
  background: var(--surface-alt); color: var(--ink);
  display: grid; place-items: center;
}
.socials a:hover { background: var(--ink); color: #fff; text-decoration: none; }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 20px;
  display: flex; justify-content: space-between; flex-wrap: wrap; gap: 12px;
  font-size: 13px; color: var(--ink-muted);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .products { grid-template-columns: repeat(3, 1fr); }
  .deal-grid { grid-template-columns: 1fr 1fr; }
  .deal-card.feature { grid-row: span 1; grid-column: span 2; }
  .editorial-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .hero-grid { grid-template-columns: 1fr; }
  .hero-copy { padding: 40px 32px; }
  .newsletter { grid-template-columns: 1fr; padding: 40px; }
  .newsletter-visual { display: none; }
}
@media (max-width: 720px) {
  .header-inner { grid-template-columns: auto auto; gap: 12px; }
  .primary-nav { display: none; }
  .products { grid-template-columns: repeat(2, 1fr); }
  .deal-grid { grid-template-columns: 1fr; }
  .deal-card.feature { grid-column: span 1; }
  .editorial-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .section-head { flex-direction: column; align-items: flex-start; }
  .hero-meta { flex-wrap: wrap; gap: 16px; }
  .hero-copy { padding: 32px 24px; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

