function Countdown({ targetMs }) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  const diff = Math.max(0, targetMs - now);
  const d = Math.floor(diff / 86400000);
  const h = Math.floor((diff % 86400000) / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  const pad = (n) => String(n).padStart(2, "0");
  return (
    <div className="countdown" role="timer" aria-live="off"
         aria-label={`Sale ends in ${d} days, ${h} hours, ${m} minutes, ${s} seconds`}>
      <div className="unit"><b>{pad(d)}</b><span>Days</span></div>
      <div className="unit"><b>{pad(h)}</b><span>Hrs</span></div>
      <div className="unit"><b>{pad(m)}</b><span>Min</span></div>
      <div className="unit"><b>{pad(s)}</b><span>Sec</span></div>
    </div>
  );
}

